import random
from collections import deque

def shortest_path(adj, u, v):
    # BFS
    if u == v:
        return 0
    visited = {u}
    q = deque([(u, 0)])
    while q:
        x, d = q.popleft()
        for y in adj[x]:
            if y == v:
                return d + 1
            if y not in visited:
                visited.add(y)
                q.append((y, d+1))
    return float('inf')

def greedy_random(num_vertices=16, target_edges=25, max_restarts=10000):
    all_edges = [(i, j) for i in range(num_vertices) for j in range(i+1, num_vertices)]
    best = []
    best_edges = 0
    for restart in range(max_restarts):
        random.shuffle(all_edges)
        adj = [set() for _ in range(num_vertices)]
        edges = []
        for u, v in all_edges:
            # check if adding edge creates cycle of length <=6
            # i.e., distance between u and v in current graph <=5
            # BFS from u to v
            # early exit if distance <=5
            dist = shortest_path(adj, u, v)
            if dist > 5:
                adj[u].add(v)
                adj[v].add(u)
                edges.append((u,v))
        if len(edges) >= target_edges:
            return edges, adj
        if len(edges) > best_edges:
            best_edges = len(edges)
            best = edges
    return None, best_edges

edges, info = greedy_random(max_restarts=5000)
