import random
from collections import deque

def bfs_dist(adj, u, v, max_dist):
    """Return True if distance from u to v is <= max_dist"""
    if u == v:
        return True
    visited = {u}
    q = deque([(u, 0)])
    while q:
        x, d = q.popleft()
        if d >= max_dist:
            continue
        for y in adj[x]:
            if y == v:
                return True
            if y not in visited:
                visited.add(y)
                q.append((y, d+1))
    return False

def is_valid_add(adj, u, v):
    # Adding edge (u,v) is valid if distance between u and v is > 5
    # (i.e., no path of length <=5 exists)
    return not bfs_dist(adj, u, v, 5)

def greedy_with_order(order, all_edges):
    adj = [set() for _ in range(16)]
    edges = []
    for idx in order:
        u, v = all_edges[idx]
        if is_valid_add(adj, u, v):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))
    return edges, adj

def try_random_orders(trials=200000):
    all_edges = [(i, j) for i in range(16) for j in range(i+1, 16)]
    best = []
