from z3 import *
import itertools

def solve_graph():
    n = 16
    num_colors = 4
    min_edges = 25

    # Edge variables
    edges = {}
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = Bool(f"e_{i}_{j}")

    # Color variables
    colors = {}
    for i in range(n):
        for c in range(num_colors):
            colors[(i,c)] = Bool(f"c_{i}_{c}")

    solver = Solver()

    # Each vertex has exactly one color
    for i in range(n):
        solver.add(Or([colors[(i,c)] for c in range(num_colors)]))
        for c1 in range(num_colors):
            for c2 in range(c1+1, num_colors):
                solver.add(Not(And(colors[(i,c1)], colors[(i,c2)])))

    # Adjacent vertices have different colors
    for i in range(n):
        for j in range(i+1, n):
            for c in range(num_colors):
                solver.add(Implies(edges[(i,j)], Not(And(colors[(i,c)], colors[(j,c)]))))

    # At least 25 edges
    edge_list = list(edges.values())
    # Use pseudo-boolean or just Or of all combinations? 
    # For at least 25, we can use PbGe
    solver.add(PbGe([(e,1) for e in edge_list], min_edges))

    # Iteratively add cycle constraints
    max_iterations = 100
    for iteration in range(max_iterations):
        print(f"Iteration {iteration}, solver status: {solver.check()}")
        if solver.check() == sat:
            model = solver.model()
            # Extract graph
            adj = [set() for _ in range(n)]
            edge_set = set()
            for (i,j), var in edges.items():
                if model.eval(var, model_completion=True):
                    adj[i].add(j)
                    adj[j].add(i)
                    edge_set.add((i,j))

            print(f"  Graph has {len(edge_set)} edges")

            # Find shortest cycle
            from collections import deque
            def find_shortest_cycle(adj, n):
                best = float('inf')
                best_cycle = None
                for start in range(n):
                    # BFS from start
                    dist = {start: 0}
                    parent = {start: None}
                    q = deque([start])
                    while q:
                        u = q.popleft()
                        for v in adj[u]:
                            if v not in dist:
                                dist[v] = dist[u] + 1
                                parent[v] = u
                                q.append(v)
                            elif parent[u] != v and parent[v] != u:
                                # Found a cycle
                                cycle_len = dist[u] + dist[v] + 1
                                if cycle_len < best:
                                    best = cycle_len
                                    # Reconstruct cycle
                                    cycle = []
                                    x, y = u, v
                                    path_x = []
                                    while x is not None:
                                        path_x.append(x)
                                        x = parent[x]
                                    path_y = []
                                    while y is not None:
                                        path_y.append(y)
                                        y = parent[y]
                                    # Find common ancestor
                                    common = None
                                    for a in path_x:
                                        if a in path_y:
                                            common = a
                                            break
                                    # Build cycle
                                    cycle = []
                                    idx = path_x.index(common)
                                    cycle = path_x[:idx+1]
                                    idx_y = path_y.index(common)
                                    cycle.extend(reversed(path_y[:idx_y]))
                                    best_cycle = cycle
                return best, best_cycle

            girth, cycle = find_shortest_cycle(adj, n)
            print(f"  Girth: {girth}")
            if girth >= 7:
                print("Found valid graph!")
                return sorted(edge_set)
            else:
                # Add constraint to forbid this cycle
                # Get all edges in the cycle
                cycle_edges = []
                for k in range(len(cycle)):
                    a, b = cycle[k], cycle[(k+1)%len(cycle)]
                    if a > b:
                        a, b = b, a
                    cycle_edges.append(edges[(a,b)])
                solver.add(Not(And(cycle_edges)))
                print(f"  Added constraint to forbid cycle of length {len(cycle)}: {cycle}")
        else:
            print("UNSAT")
            return None

    return None

result = solve_graph()
print("Result:", result)
